    case "complete":
      save(path, complete(todos, cmd.id));
      return `Completed #${cmd.id}`;
    case "list": {
      const options: ListOptions = {};
      if (cmd.verbose) {
        options.includeDone = false;
      }
      return list(todos, options);
    }
  }
}

