import { parseArgs, list } from "../../src/commands";
import { formatList } from "../../src/format";

describe("commands", () => {
  test("parseArgs parses each command", () => {
    const cmd = parseArgs(["add", "milk"]);
    expect(cmd).toEqual({ kind: "add", title: "milk" });
  });

  test("parseArgs handles list command without --verbose", () => {
    const cmd = parseArgs(["list"]);
    expect(cmd).toEqual({ kind: "list" });
  });

  test("parseArgs handles list command with --verbose", () => {
    const cmd = parseArgs(["list", "--verbose"]);
    expect(cmd).toEqual({ kind: "list", verbose: true });
  });
});

describe("formatList", () => {
  test("formatList without verbose shows simple titles", () => {
    const todos = [{ id: 1, title: "milk", done: false }, { id: 2, title: "eggs", done: true }];
    const output = formatList(todos);
    expect(output).toBe("- milk\n- eggs\n");
  });

  test("formatList with verbose shows task details", () => {
    const todos = [
      { id: 1, title: "milk", done: false, due: "tomorrow" },
      { id: 2, title: "eggs", done: true, due: "never" }
    ];
    const output = formatList(todos, true);
    expect(output).toContain("#1 milk (not done)\n#2 eggs (done)\n");
  });
});
